import{_ as e,c as r,o as a,b0 as n}from"./chunks/framework.Dmsv_Tiv.js";const A="/media-docs/assets/image-20240609084445706.LItDthHH.png",o="/media-docs/assets/300px-Light_dispersion_conceptual_waves350px.Dh4KzFNh.gif",l="/media-docs/assets/640px-EM_spectrum_zh-hans.svg.DyaCpVTT.png",w="data:image/png;base64,",p=JSON.parse('{"title":"LV001-基础知识","description":null,"frontmatter":{"title":"LV001-基础知识","date":"2025-09-18T16:04:42.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/image/color/126b08c8883a1ae2b4135020","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-09-18T16:04:42.430Z","fulluuid":"2b41350204204bd69b2b5119c2aa329b","useduuid":"2b4135020"}},"headers":[],"relativePath":"sdoc/image/color/126b08c8883a1ae2b4135020.md","filePath":"sdoc/01-图像/10-色彩基础/LV001-基础知识.md","lastUpdated":1767537778000}'),h={name:"sdoc/image/color/126b08c8883a1ae2b4135020.md"};function i(s,t,d,c,g,E){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="lv001-基础知识" tabindex="-1">LV001-基础知识 <a class="header-anchor" href="#lv001-基础知识" aria-label="Permalink to &quot;LV001-基础知识&quot;">​</a></h1><h2 id="一、什么是颜色" tabindex="-1">一、什么是颜色？ <a class="header-anchor" href="#一、什么是颜色" aria-label="Permalink to &quot;一、什么是颜色？&quot;">​</a></h2><p>颜色是通过眼、脑和我们的生活经验所产生的对光的视觉感受，我们肉眼所见到的光线，是由波长范围很窄的电磁波产生的，不同波长的电磁波表现为不同的颜色，对色彩的辨认是肉眼受到电磁波辐射能刺激后所引起的视觉神经感觉。</p><h2 id="二、可见光是什么" tabindex="-1">二、可见光是什么 <a class="header-anchor" href="#二、可见光是什么" aria-label="Permalink to &quot;二、可见光是什么&quot;">​</a></h2><p><a href="https://www.wikiwand.com/zh-cn/%E5%8F%AF%E8%A7%81%E5%85%89#introduction" target="_blank" rel="noreferrer"><strong>可见光</strong>（英语：visible light）</a>是人类可看见的电磁波，其波长范围一般是落在360 - 400 nm ~ 760 - 830nm，这段电磁波谱又称为可见光谱（visible spectrum），其频率范围在830 - 750THz ~ 395 - 360THz 。这个范围因人而异，部分人群甚至可以看到310nm的紫外光或是1100nm的近红外光。</p><p>13世纪，罗杰·培根提出彩虹形成的过程与光线透过玻璃或水晶的情况类似。17世纪，牛顿发现棱镜可以分解和重组白光，并将这发现写在《光学》著作上。如下图所示，为白光通过棱镜看到的色谱。</p><img src="'+A+'" alt="image-20240609084445706" style="zoom:50%;"><p>这里还有一个动态图：</p><img src="'+o+'" alt="img" style="zoom:80%;"><p>早期对光谱的2种解说来自于艾萨克·牛顿的光学和歌德的色彩学。牛顿首先在1671年在他的光学试验的说明中使用了光谱这个字（在拉丁文中代表外观、显象）。牛顿观察到一束阳光以一个角度射入玻璃棱镜，部分会被反射，部分则穿透玻璃，并呈现出不同的色带。牛顿假定阳光是由不同颜色的小粒子组成，而这些不同颜色在穿透物质时，前进速度不同。而红光的速度快于紫光，而导致了在穿过棱镜后红光的偏折（折射）较紫光为小，产生各色的光谱。</p><p>牛顿把光谱分成7种颜色（英语：ROYGBIV）：红、橙、黄、绿、蓝、靛、紫。他依古希腊哲学家的想法，选这7种颜色，并和音符、太阳系已知的7颗行星、和一周7天做连结。然而人眼对于靛色频率的敏感度其实是相对较差的，加之一些辨色能力正常的人都表示他们无法区分靛色和蓝色、紫色。正因此之故，一些专家如艾萨克·阿西莫夫等都曾建议靛色不应被视为颜色，它只是蓝和紫的浓淡不同的区间而已。有证据表明，牛顿当年提出的蓝色、靛色与现代定义不同，当年的蓝色是青色，而靛色是蓝色。</p><p>18世纪，歌德在他的色彩学（英语：Theory of Colours）提到了光谱，歌德使用光谱代表残影（英语：Afterimage）。哥德声称连续光谱是个复合现象，而牛顿则认为仅限可见光光谱是个单独现象，哥德观察到了更广泛的部分，他发现到了没有光谱的区间，如红黄边界和青蓝边界是白的，原来在边界区会有色光重叠的现象。19世纪，因为红外光与紫外光的发现，可见光谱概念更加明确。1802年，杨格第一次测量不同颜色可见光的波长。</p><p>下图是可见光电磁波谱的波长组成部分，我们能感受到的可见光的光谱范围只占电磁波的一小部分。</p><img src="'+l+'" alt="可见光谱只占有宽广的电磁波谱的一小部分"><h2 id="三、光谱色" tabindex="-1">三、光谱色 <a class="header-anchor" href="#三、光谱色" aria-label="Permalink to &quot;三、光谱色&quot;">​</a></h2><img src="'+w+'" alt="sRGB rendering of the spectrum of visible light"><table tabindex="0"><thead><tr><th style="text-align:center;"><a href="https://www.wikiwand.com/zh-cn/%E9%A1%8F%E8%89%B2" target="_blank" rel="noreferrer">颜色</a></th><th><a href="https://www.wikiwand.com/zh-cn/%E9%A0%BB%E7%8E%87" target="_blank" rel="noreferrer">频率</a> (THz)</th><th><a href="https://www.wikiwand.com/zh-cn/%E6%B3%A2%E9%95%B7" target="_blank" rel="noreferrer">波长</a> (nm)</th><th>能量 (eV)</th></tr></thead><tbody><tr><td style="text-align:center;"><strong><a href="https://www.wikiwand.com/zh-cn/%E7%B4%AB%E8%89%B2" target="_blank" rel="noreferrer">紫色</a></strong></td><td>666–789</td><td>380–450</td><td>2.76–3.26</td></tr><tr><td style="text-align:center;"><strong><a href="https://www.wikiwand.com/zh-cn/%E8%93%9D%E8%89%B2" target="_blank" rel="noreferrer">蓝色</a></strong></td><td>631–666</td><td>450–475</td><td>2.61–2.76</td></tr><tr><td style="text-align:center;"><strong><a href="https://www.wikiwand.com/zh-cn/%E9%9D%92%E8%89%B2" target="_blank" rel="noreferrer">青色</a></strong></td><td>606–631</td><td>475–495</td><td>2.50–2.61</td></tr><tr><td style="text-align:center;"><strong><a href="https://www.wikiwand.com/zh-cn/%E7%B6%A0%E8%89%B2" target="_blank" rel="noreferrer">绿色</a></strong></td><td>526–606</td><td>495–570</td><td>2.18–2.50</td></tr><tr><td style="text-align:center;"><strong><a href="https://www.wikiwand.com/zh-cn/%E9%BB%83%E8%89%B2" target="_blank" rel="noreferrer">黄色</a></strong></td><td>508–526</td><td>570–590</td><td>2.10–2.18</td></tr><tr><td style="text-align:center;"><strong><a href="https://www.wikiwand.com/zh-cn/%E6%A9%99%E8%89%B2" target="_blank" rel="noreferrer">橙色</a></strong></td><td>484–508</td><td>590–620</td><td>2.00–2.10</td></tr><tr><td style="text-align:center;"><strong><a href="https://www.wikiwand.com/zh-cn/%E7%B4%85%E8%89%B2" target="_blank" rel="noreferrer">红色</a></strong></td><td>400–484</td><td>620–750</td><td>1.65–2.00</td></tr></tbody></table><h2 id="四、原色及三原色" tabindex="-1">四、原色及三原色 <a class="header-anchor" href="#四、原色及三原色" aria-label="Permalink to &quot;四、原色及三原色&quot;">​</a></h2><p>没找到定义，不过，还待是维基百科啊：</p><blockquote><p>原色：可叠加产生其他颜色的颜色</p></blockquote><p><strong>原色</strong>（primary color）是不能透过其他<a href="https://www.wikiwand.com/zh-hans/%E9%A1%8F%E8%89%B2" target="_blank" rel="noreferrer">颜色</a>的混合调配而得出的“基本色”；将不同比例的原色混合，可生成<a href="https://www.wikiwand.com/zh-hans/%E8%89%B2%E5%9F%9F" target="_blank" rel="noreferrer">色域</a>内其他任何颜色。</p><p>以数学的<a href="https://www.wikiwand.com/zh-hans/%E5%90%91%E9%87%8F%E7%A9%BA%E9%96%93" target="_blank" rel="noreferrer">向量空间</a>来解释<a href="https://www.wikiwand.com/zh-hans/%E8%89%B2%E5%BD%A9" target="_blank" rel="noreferrer">色彩</a>系统，则原色在空间内可作为一组<a href="https://www.wikiwand.com/zh-hans/%E5%9F%BA%E5%BA%95" target="_blank" rel="noreferrer">基底</a><a href="https://www.wikiwand.com/zh-hans/%E5%90%91%E9%87%8F" target="_blank" rel="noreferrer">向量</a>，并且能组合出一个“色彩空间”。由于人类肉眼有三种不同颜色的感光体，因此所见的色彩空间通常可以由三种基本色所表达，这三种颜色被称为“<strong>三原色</strong>”。一般来说叠加型的三原色是<a href="https://www.wikiwand.com/zh-hans/%E7%B4%85%E8%89%B2" target="_blank" rel="noreferrer">红色</a>、<a href="https://www.wikiwand.com/zh-hans/%E7%B6%A0%E8%89%B2" target="_blank" rel="noreferrer">绿色</a>、<a href="https://www.wikiwand.com/zh-hans/%E8%93%9D%E8%89%B2" target="_blank" rel="noreferrer">蓝色</a>（又称三基色，用于电视机、投影仪等显示设备；而消减型的三原色是<a href="https://www.wikiwand.com/zh-hans/%E6%B4%8B%E7%B4%85%E8%89%B2" target="_blank" rel="noreferrer">品红色</a>、<a href="https://www.wikiwand.com/zh-hans/%E9%BB%83%E8%89%B2" target="_blank" rel="noreferrer">黄色</a>、<a href="https://www.wikiwand.com/zh-hans/%E9%9D%92%E8%89%B2" target="_blank" rel="noreferrer">青色</a>（用于书本、杂志等的印刷）。</p><p>“原色”并非是一种<a href="https://www.wikiwand.com/zh-hans/%E7%89%A9%E7%90%86" target="_blank" rel="noreferrer">物理</a>概念，而是一种<a href="https://www.wikiwand.com/zh-hans/%E7%94%9F%E7%89%A9%E5%AD%B8" target="_blank" rel="noreferrer">生物学</a>的概念，是基于人的肉眼对于<a href="https://www.wikiwand.com/zh-hans/%E5%85%89%E7%B7%9A" target="_blank" rel="noreferrer">光线</a>的生理作用。人的眼睛内有几种辨别颜色的<a href="https://www.wikiwand.com/zh-hans/%E9%8C%90%E7%8B%80%E7%B4%B0%E8%83%9E" target="_blank" rel="noreferrer">锥状细胞</a>，分别对黄绿色、绿色和蓝紫色（564、534和420纳米波长）的光最敏感。人类以及其他具有这三种感光受体的生物称为“三色感光体生物”。虽然眼球中的椎状细胞并非对红、绿、蓝三色的感受度最强，但是由肉眼的椎状细胞所能感受的光的频宽很大，红、绿、蓝也能够独立刺激这三种颜色的受光体，因此这三色被视为原色。</p>',23)])])}const k=e(h,[["render",i]]);export{p as __pageData,k as default};
